#!/bin/sh
# lib/*.js -> film.js (lib/assemble.py) -> page. film.json is generated by lib/mkfilm.py (knobs, captions) and film.js by lib/assemble.py; run from anywhere.
set -e
D=$(cd "$(dirname "$0")" && pwd)
python3 "$D/lib/mkfilm.py" && python3 "$D/lib/assemble.py" && node --check "$D/film.js" && cd "$D/../../../../.." && python3 factory/kit2/build.py factory/films/noether-applied/drafts/b --brand ceti-coastal-dark --chrome none --material ink | grep -v "^note"
